import {
  PanDirection,
  handlePanningMovement,
} from '../../../../core/functions/zoom.js';
import { useSetState } from '../../../hooks/store/selectors.js';
import { useHistogramInteractions } from '../../../hooks/useHistogramInteractions.js';
import { useHistogramXScale } from '../../../hooks/useHistogramXScale.js';

export const usePanningKeyboardMovementHandlers = () => {
  const { xScale, initialXScale } = useHistogramXScale();
  const { onZoomChange } = useHistogramInteractions();
  const initialXScaleDomain = initialXScale.domain();
  const setState = useSetState();

  const keyboardPanning = (direction: PanDirection) => (largeStep: boolean) => {
    const newDomain = handlePanningMovement(
      xScale,
      direction,
      largeStep ? 'large' : 'small',
      initialXScaleDomain,
    ) as number[];
    const [start, end] = newDomain;
    onZoomChange?.(start, end, 'panning');

    setState((prev) => ({ ...prev, currentDomain: newDomain }));
  };

  return {
    keyboardPanning,
  };
};
